CREATE TABLE IF NOT EXISTS admins (user_id TEXT PRIMARY KEY, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL UNIQUE, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS news_sources (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, feed_url TEXT NOT NULL UNIQUE, category_id INTEGER REFERENCES categories(id), max_items INTEGER NOT NULL DEFAULT 2 CHECK (max_items >= 1 AND max_items <= 20), enabled INTEGER NOT NULL DEFAULT 1, last_fetched_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), priority INTEGER NOT NULL DEFAULT 0, language TEXT NOT NULL DEFAULT 'en');
CREATE TABLE IF NOT EXISTS articles (id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))), slug TEXT UNIQUE, title TEXT NOT NULL, subtitle TEXT, body TEXT NOT NULL DEFAULT '', category_id INTEGER REFERENCES categories(id), author TEXT NOT NULL DEFAULT 'Buza Media', tags TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','archived')), is_breaking INTEGER NOT NULL DEFAULT 0, is_featured INTEGER NOT NULL DEFAULT 0, orientation TEXT NOT NULL DEFAULT 'landscape' CHECK (orientation IN ('landscape','portrait','square')), image_url TEXT, image_width INTEGER, image_height INTEGER, video_url TEXT, source_id INTEGER REFERENCES news_sources(id), source_name TEXT, source_url TEXT, source_caption TEXT, ai_generated INTEGER NOT NULL DEFAULT 0, view_count INTEGER NOT NULL DEFAULT 0, like_count INTEGER NOT NULL DEFAULT 0, published_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), language TEXT NOT NULL DEFAULT 'sw', short_code TEXT NOT NULL DEFAULT (substr(lower(hex(randomblob(8))),1,8)), dedupe_key TEXT, source_title TEXT, notified_at TEXT, title_en TEXT, subtitle_en TEXT, body_en TEXT);
CREATE TABLE IF NOT EXISTS article_likes (article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE, visitor_id TEXT NOT NULL CHECK (length(visitor_id) >= 8 AND length(visitor_id) <= 64), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY (article_id, visitor_id));
CREATE TABLE IF NOT EXISTS ai_generations (id INTEGER PRIMARY KEY AUTOINCREMENT, article_id TEXT REFERENCES articles(id) ON DELETE SET NULL, purpose TEXT NOT NULL CHECK (purpose IN ('article','caption','image','daily_report')), model TEXT NOT NULL, prompt TEXT, output TEXT, tokens_in INTEGER, tokens_out INTEGER, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS daily_reports (id INTEGER PRIMARY KEY AUTOINCREMENT, report_date TEXT NOT NULL UNIQUE, title TEXT NOT NULL, summary TEXT NOT NULL, article_ids TEXT NOT NULL DEFAULT '[]', cover_image_url TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS social_accounts (platform TEXT PRIMARY KEY CHECK (platform IN ('instagram','facebook','tiktok')), account_ref TEXT, display_handle TEXT, collaborator_username TEXT, enabled INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS social_credentials (platform TEXT PRIMARY KEY REFERENCES social_accounts(platform) ON DELETE CASCADE, access_token TEXT NOT NULL, token_expires_at TEXT, updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS social_posts (id INTEGER PRIMARY KEY AUTOINCREMENT, article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE, platform TEXT NOT NULL CHECK (platform IN ('instagram','facebook','tiktok')), status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','processing','published','failed','skipped')), caption TEXT, image_url TEXT, image_width INTEGER, image_height INTEGER, external_post_id TEXT, attempts INTEGER NOT NULL DEFAULT 0, next_retry_at TEXT, error TEXT, posted_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS trending_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, started_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), finished_at TEXT, status TEXT NOT NULL DEFAULT 'running' CHECK (status IN ('running','success','partial','failed')), found INTEGER NOT NULL DEFAULT 0, inserted INTEGER NOT NULL DEFAULT 0, error TEXT);
CREATE TABLE IF NOT EXISTS job_locks (name TEXT PRIMARY KEY, locked_until TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS site_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, is_public INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS app_secrets (name TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS push_subscriptions (id INTEGER PRIMARY KEY AUTOINCREMENT, endpoint TEXT NOT NULL UNIQUE CHECK (endpoint LIKE 'https://%' AND length(endpoint) < 1200), p256dh TEXT NOT NULL CHECK (length(p256dh) < 200), auth TEXT NOT NULL CHECK (length(auth) < 100), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS idx_articles_status_published ON articles(status, published_at DESC);
CREATE INDEX IF NOT EXISTS idx_articles_category ON articles(category_id);
CREATE INDEX IF NOT EXISTS idx_articles_short_code ON articles(short_code);
CREATE UNIQUE INDEX IF NOT EXISTS idx_articles_dedupe_key ON articles(dedupe_key) WHERE dedupe_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_articles_language ON articles(language);
CREATE INDEX IF NOT EXISTS idx_social_posts_article ON social_posts(article_id);
CREATE INDEX IF NOT EXISTS idx_social_posts_status ON social_posts(status, next_retry_at);
CREATE INDEX IF NOT EXISTS idx_article_likes_article ON article_likes(article_id);
CREATE TRIGGER IF NOT EXISTS trg_articles_updated AFTER UPDATE ON articles FOR EACH ROW WHEN NEW.updated_at = OLD.updated_at BEGIN UPDATE articles SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = NEW.id; END;
CREATE TRIGGER IF NOT EXISTS trg_social_posts_updated AFTER UPDATE ON social_posts FOR EACH ROW WHEN NEW.updated_at = OLD.updated_at BEGIN UPDATE social_posts SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = NEW.id; END;
